    std::string s2 = FUZZ_PARAM_STR(); if (s2.size() > 16) s2.resize(16);

    isc::dhcp::OptionBuffer buf;
    auto emit_tuple = [&](const std::string& s){
        size_t n = s.size();
        if (L == 1) {
            uint8_t l = static_cast<uint8_t>(n & 0xFFu);
            buf.push_back(l);
        } else {
            uint16_t l = static_cast<uint16_t>(n & 0xFFFFu);
            buf.push_back(static_cast<uint8_t>((l >> 8) & 0xFF));
            buf.push_back(static_cast<uint8_t>(l & 0xFF));
